mapper.select:
SELECT project_id
  FROM project
 WHERE approval_status = #{approvalStatus}

       AND user_id = #{makerId}

 ORDER BY created_at DESC, project_id DESC
 LIMIT 1

SELECT p.project_id, p.project_name, p.project_status, p.start_date, p.end_date, p.target_amount, r.reward_id, r.reward_name, r.reward_price, r.reward_amount, r.applied_count, f.user_id AS funder_id, u.user_name AS funder_name, u.phone_number AS funder_phone, s.delivery_address, f.funded_date FROM project p LEFT JOIN reward r ON r.project_id = p.project_id LEFT JOIN funding f ON f.reward_id = r.reward_id LEFT JOIN `user` u ON u.user_id = f.user_id LEFT JOIN supporter s ON s.user_id = f.user_id WHERE p.user_id = #{makerId} AND p.approval_status = 'approved'
AND p.project_id = #{projectId}
ORDER BY p.created_at DESC, p.project_id DESC, r.reward_id, f.funded_date
